#!/usr/bin/env node
// Builds the OpenAI plugin (ChatGPT apps + Codex plugins directory) from openai-plugin/.
//
//   node scripts/build-openai-plugin.mjs                 regenerate openai-plugin/skills, then validate
//   node scripts/build-openai-plugin.mjs --check         fail if openai-plugin/skills is stale, then validate
//   node scripts/build-openai-plugin.mjs --zip out.zip   regenerate, validate, write the upload ZIP
//
// Skills are derived from plugins/chatacademia/skills (generated by sync-skills.mjs from the server), adapted to the
// reviewed /mcp/chatgpt route: only tools that route exposes, no checkout, upgrade or price wording.
// Validation follows https://developers.openai.com/plugins/deploy/submission-errors (no official CLI validator exists).

import { createHash } from "node:crypto";
import {
	existsSync,
	mkdirSync,
	readdirSync,
	readFileSync,
	rmSync,
	statSync,
	writeFileSync,
} from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { crc32, deflateRawSync } from "node:zlib";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const pluginDir = join(root, "openai-plugin");
const claudeSkills = join(root, "plugins/chatacademia/skills");
const args = process.argv.slice(2);
const check = args.includes("--check");
const zipOut = args.includes("--zip") ? resolve(args[args.indexOf("--zip") + 1] ?? "") : null;

// Tools served on https://api.chatacademia.com/mcp/chatgpt (CA create-research-mcp-handler.ts: the reviewed route
// hides get_my_memory, remember_about_me and the upgrade tools). Keep in sync when that route changes.
const chatgptTools = new Set([
	"search_papers", "get_paper_evidence", "search_grants", "verify_citations",
	"brainstorm_research_questions", "refine_research_question", "generate_research_subquestions",
	"create_search_strategy", "design_research_study", "create_review_protocol", "identify_research_gaps",
	"synthesize_literature", "evaluate_research_claim", "summarize_academic_text", "extract_study_data",
	"review_manuscript", "improve_academic_writing", "assess_grant_fit", "create_poster_outline",
	"prepare_academic_seminar", "list_research_workflows", "get_research_workflow",
	"get_user_info", "get_current_plan", "get_credit_balance", "get_tool_credit_costs",
	"get_mcp_usage_summary", "list_mcp_tool_calls", "submit_feedback",
]);
const hiddenTools = ["get_my_memory", "remember_about_me", "list_upgrade_plans", "create_upgrade_checkout"];
const forbiddenWords = /\b(checkout|upgrade|upgrading|price|prices|pricing|subscription|subscribe|purchase|buy|discount|coupon)\b|\$\d/i;

const errors = [];
const fail = (message) => errors.push(message);

// ---------------------------------------------------------------- skills
function adaptSkill(source, dir) {
	let text = source.replace(
		/<!-- Generated by scripts\/sync-skills\.mjs[^>]*-->/,
		"<!-- Generated by scripts/build-openai-plugin.mjs from plugins/chatacademia/skills. Do not edit by hand. -->",
	);
	text = text.replace(
		"Use the ChatAcademia connector bundled with this plugin.",
		"Use the ChatAcademia app bundled with this plugin.",
	);
	text = text.replace(
		"- Only submit feedback, create checkout links or use other account tools when the user explicitly asks.",
		"- Only submit feedback or use account tools when the user explicitly asks.",
	);
	for (const tool of hiddenTools)
		if (text.includes(tool)) fail(`skills/${dir}: mentions ${tool}, which /mcp/chatgpt does not expose`);
	const toolList = text.match(/## Tools\n\n((?:- .+\n)+)/);
	if (!toolList) fail(`skills/${dir}: no "## Tools" list`);
	else
		for (const line of toolList[1].trim().split("\n")) {
			const tool = line.slice(2).trim();
			if (!chatgptTools.has(tool)) fail(`skills/${dir}: tool ${tool} is not on /mcp/chatgpt`);
		}
	const forbidden = text.match(forbiddenWords);
	if (forbidden) fail(`skills/${dir}: commerce wording "${forbidden[0]}"`);
	if (/\bClaude\b/.test(text)) fail(`skills/${dir}: mentions Claude`);
	return text;
}

const generated = new Map();
for (const dir of readdirSync(claudeSkills).sort()) {
	const file = join(claudeSkills, dir, "SKILL.md");
	if (existsSync(file)) generated.set(dir, adaptSkill(readFileSync(file, "utf8"), dir));
}
const skillsDir = join(pluginDir, "skills");
if (check) {
	const existing = existsSync(skillsDir) ? readdirSync(skillsDir).sort() : [];
	if (existing.join() !== [...generated.keys()].join()) fail("openai-plugin/skills is stale: run the script");
	for (const [dir, text] of generated)
		if (!existsSync(join(skillsDir, dir, "SKILL.md")) || readFileSync(join(skillsDir, dir, "SKILL.md"), "utf8") !== text)
			fail(`openai-plugin/skills/${dir}/SKILL.md is stale: run the script`);
} else {
	rmSync(skillsDir, { recursive: true, force: true });
	for (const [dir, text] of generated) {
		mkdirSync(join(skillsDir, dir), { recursive: true });
		writeFileSync(join(skillsDir, dir, "SKILL.md"), text);
	}
}

// ---------------------------------------------------------------- manifest
const readJSON = (file) => {
	try {
		return JSON.parse(readFileSync(join(pluginDir, file), "utf8"));
	} catch (error) {
		fail(`${file}: ${error.message}`);
		return {};
	}
};
const manifest = readJSON(".codex-plugin/plugin.json");
const ui = manifest.interface ?? {};
const len = (value) => [...(value ?? "")].length;
const https = (value) => {
	try {
		const url = new URL(value);
		return url.protocol === "https:" && !url.username && !url.password && value.length <= 1024;
	} catch {
		return false;
	}
};
const oneLine = (value) => typeof value === "string" && !/[\r\n]/.test(value);

if (manifest.name !== "chatacademia-research") fail("name must stay chatacademia-research (existing listing)");
if (!/^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/.test(manifest.name ?? "")) fail("name format");
if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/.test(manifest.version ?? "")) fail("version must be semver");
if (!manifest.description || len(manifest.description) > 1024) fail("description required, ≤1,024 chars");
if (!manifest.author?.name || len(manifest.author.name) > 120) fail("author.name required, ≤120 chars");
if (manifest.author?.url && !https(manifest.author.url)) fail("author.url must be HTTPS");
if (manifest.homepage && !https(manifest.homepage)) fail("homepage must be HTTPS");
if ((manifest.keywords ?? []).length > 25) fail("≤25 keywords");
if (manifest.skills !== "./skills/") fail('skills must be "./skills/"');
if (manifest.mcpServers !== "./.mcp.json") fail('mcpServers must be "./.mcp.json"');
for (const key of ["apps", "hooks", "userConfig", "outputStyles", "lspServers", "channels", "dependencies", "experimental"])
	if (key in manifest) fail(`${key} is not allowed in a directory package`);
if (!ui.displayName || len(ui.displayName) > 30) fail("interface.displayName required, ≤30 chars");
if (!oneLine(ui.shortDescription) || len(ui.shortDescription) > 30) fail("interface.shortDescription one line, ≤30 chars");
if (!ui.longDescription || len(ui.longDescription) > 4000) fail("interface.longDescription required, ≤4,000 chars");
if (!ui.developerName || len(ui.developerName) > 80) fail("interface.developerName required, ≤80 chars");
const categories = ["Productivity", "Creativity", "Developer Tools", "Business & Operations", "Data & Analytics",
	"Communication", "Education & Research", "Security", "Finance", "Healthcare", "Travel", "Entertainment", "Other"];
if (!categories.includes(ui.category)) fail(`interface.category must be one of: ${categories.join(", ")}`);
if (!Array.isArray(ui.capabilities) || ui.capabilities.length > 20) fail("interface.capabilities: list, ≤20");
for (const capability of ui.capabilities ?? [])
	if (!oneLine(capability) || !capability || len(capability) > 120) fail(`capability "${capability}" must be one line, ≤120 chars`);
for (const key of ["websiteURL", "supportURL", "privacyPolicyURL", "termsOfServiceURL"])
	if (!https(ui[key])) fail(`interface.${key} must be an HTTPS URL (required for MCP review)`);
const prompts = ui.defaultPrompt ?? [];
if (prompts.length > 3 || new Set(prompts).size !== prompts.length) fail("≤3 unique defaultPrompt entries");
for (const prompt of prompts)
	if (!oneLine(prompt) || !prompt || len(prompt) > 128 || /@\w/.test(prompt)) fail(`defaultPrompt "${prompt}" must be one line, ≤128 chars, no @mentions`);
const luminance = (hex) => {
	const [r, g, b] = [1, 3, 5].map((i) => {
		const c = Number.parseInt(hex.slice(i, i + 2), 16) / 255;
		return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
	});
	return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
const contrast = (a, b) => (Math.max(luminance(a), luminance(b)) + 0.05) / (Math.min(luminance(a), luminance(b)) + 0.05);
for (const [key, against] of [["brandColor", "#FFFFFF"], ["brandColorDark", "#212121"]])
	if (ui[key] !== undefined && (!/^#[0-9A-Fa-f]{6}$/.test(ui[key]) || contrast(ui[key], against) < 2))
		fail(`interface.${key} must be #RRGGBB with ≥2:1 contrast against ${against}`);
for (const text of [manifest.description, ui.longDescription, ui.shortDescription, ...(ui.capabilities ?? []), ...prompts]) {
	const forbidden = (text ?? "").match(forbiddenWords);
	if (forbidden) fail(`listing text has commerce wording "${forbidden[0]}"`);
}

// Square PNG between 48 and 4096 px, ≤5 MiB.
function checkImage(key) {
	const path = ui[key];
	if (!path) return fail(`interface.${key} is required`);
	if (!path.startsWith("./") || path.includes("..")) return fail(`interface.${key} must be a ./ relative path`);
	const file = join(pluginDir, path);
	if (!existsSync(file)) return fail(`interface.${key}: ${path} missing`);
	const data = readFileSync(file);
	if (data.length > 5 * 1024 * 1024) fail(`interface.${key}: larger than 5 MiB`);
	if (!path.endsWith(".png") || data.toString("latin1", 1, 4) !== "PNG") return fail(`interface.${key}: expected a PNG`);
	const width = data.readUInt32BE(16);
	const height = data.readUInt32BE(20);
	if (width !== height || width < 48 || width > 4096) fail(`interface.${key}: ${width}x${height}, must be square 48–4096 px`);
}
checkImage("logo");
checkImage("composerIcon");

// ---------------------------------------------------------------- MCP config
const mcp = readJSON(".mcp.json");
const servers = Object.entries(mcp.mcpServers ?? {});
if (servers.length !== 1) fail(".mcp.json must declare exactly one MCP server");
for (const [name, server] of servers) {
	if (server.url !== "https://api.chatacademia.com/mcp/chatgpt") fail(`.mcp.json ${name}: URL must stay https://api.chatacademia.com/mcp/chatgpt (reviewed surface)`);
	if (server.headers && Object.keys(server.headers).length) fail(`.mcp.json ${name}: headers are not allowed`);
	if (JSON.stringify(server).includes("clientSecret")) fail(`.mcp.json ${name}: clientSecret is not allowed`);
}

// ---------------------------------------------------------------- package files
function walk(dir) {
	return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
		const path = join(dir, entry.name);
		if (entry.isSymbolicLink()) {
			fail(`${relative(pluginDir, path)}: symlinks are not allowed`);
			return [];
		}
		return entry.isDirectory() ? walk(path) : [path];
	});
}
const files = walk(pluginDir)
	.map((file) => relative(pluginDir, file))
	.filter((file) => file !== "README.md")
	.sort();
const allowed = /^(\.codex-plugin\/plugin\.json|\.mcp\.json|assets\/[a-z0-9-]+\.png|skills\/[a-z0-9-]+\/SKILL\.md)$/;
for (const file of files) {
	if (!allowed.test(file)) fail(`unexpected file in package: ${file}`);
	if (/(^|\/)(\.app\.json|hooks|test_credentials|reviewer_instructions)/.test(file)) fail(`forbidden file: ${file}`);
}
const skillNames = new Set();
for (const file of files.filter((f) => f.startsWith("skills/"))) {
	const text = readFileSync(join(pluginDir, file), "utf8");
	const dir = file.split("/")[1];
	const front = text.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
	if (!front) {
		fail(`${file}: missing YAML front matter`);
		continue;
	}
	const name = front[1].match(/^name:\s*(.+)$/m)?.[1].trim();
	const descriptionLine = front[1].match(/^description:\s*(.+)$/m)?.[1].trim();
	const description = descriptionLine?.startsWith('"') ? JSON.parse(descriptionLine) : descriptionLine;
	if (!name || name !== dir || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(name)) fail(`${file}: name must equal the directory, lowercase-hyphen`);
	if (`${manifest.name}:${name}`.length > 64) fail(`${file}: ${manifest.name}:${name} longer than 64 chars`);
	if (skillNames.has(name)) fail(`${file}: duplicate skill name`);
	skillNames.add(name);
	if (!description || len(description) > 1024) fail(`${file}: description required, ≤1,024 chars`);
	if (!front[2].trim()) fail(`${file}: empty body`);
}
if (skillNames.size === 0) fail("at least one skill is required");

if (errors.length) {
	console.error(`OpenAI plugin validation failed (${errors.length}):\n- ${errors.join("\n- ")}`);
	process.exit(1);
}
console.log(`OpenAI plugin ${manifest.name}@${manifest.version} valid: ${skillNames.size} skills, ${files.length} files.`);

// ---------------------------------------------------------------- ZIP (deterministic, stored at the archive root)
if (zipOut) {
	const local = [];
	const central = [];
	let offset = 0;
	const dosTime = 0; // 00:00:00
	const dosDate = ((2026 - 1980) << 9) | (1 << 5) | 1; // 2026-01-01
	for (const file of files) {
		const data = readFileSync(join(pluginDir, file));
		const compressed = deflateRawSync(data, { level: 9 });
		const name = Buffer.from(file, "utf8");
		const crc = crc32(data);
		const header = Buffer.alloc(30);
		header.writeUInt32LE(0x04034b50, 0);
		header.writeUInt16LE(20, 4);
		header.writeUInt16LE(0x0800, 6); // UTF-8 names
		header.writeUInt16LE(8, 8); // deflate
		header.writeUInt16LE(dosTime, 10);
		header.writeUInt16LE(dosDate, 12);
		header.writeUInt32LE(crc, 14);
		header.writeUInt32LE(compressed.length, 18);
		header.writeUInt32LE(data.length, 22);
		header.writeUInt16LE(name.length, 26);
		local.push(header, name, compressed);
		const entry = Buffer.alloc(46);
		entry.writeUInt32LE(0x02014b50, 0);
		entry.writeUInt16LE((3 << 8) | 20, 4); // made by Unix
		entry.writeUInt16LE(20, 6);
		entry.writeUInt16LE(0x0800, 8);
		entry.writeUInt16LE(8, 10);
		entry.writeUInt16LE(dosTime, 12);
		entry.writeUInt16LE(dosDate, 14);
		entry.writeUInt32LE(crc, 16);
		entry.writeUInt32LE(compressed.length, 20);
		entry.writeUInt32LE(data.length, 24);
		entry.writeUInt16LE(name.length, 28);
		entry.writeUInt32LE((0o100644 << 16) >>> 0, 38); // regular file, rw-r--r--
		entry.writeUInt32LE(offset, 42);
		central.push(entry, name);
		offset += header.length + name.length + compressed.length;
	}
	const centralSize = central.reduce((sum, part) => sum + part.length, 0);
	const end = Buffer.alloc(22);
	end.writeUInt32LE(0x06054b50, 0);
	end.writeUInt16LE(files.length, 8);
	end.writeUInt16LE(files.length, 10);
	end.writeUInt32LE(centralSize, 12);
	end.writeUInt32LE(offset, 16);
	const zip = Buffer.concat([...local, ...central, end]);
	if (zip.length > 100 * 1000 * 1000) fail("ZIP larger than 100 MB");
	mkdirSync(dirname(zipOut), { recursive: true });
	writeFileSync(zipOut, zip);
	const sha = createHash("sha256").update(zip).digest("hex");
	console.log(`Wrote ${zipOut} (${statSync(zipOut).size} bytes, ${files.length} entries, sha256 ${sha})`);
}
